INSERT INTO __DB__.__SCHEMA__.DOC_EXTRACT (STAGE_PATH, PRODUCT_SLUG, DOC_TYPE, EXTRACTED, SCORES, ERR)
SELECT 'sample_emulsifier/sample-spec_A-100.pdf', 'sample_emulsifier', 'spec', PARSE_JSON($${"product_name":"サンプル乳化剤 A-100","maker_name":"サンプルケミカル工業","inci_name":"Sample Glyceryl Ester (fictional)","display_name":"サンプルグリセリルエステル","standard_basis":"自主規格","origin_type":"植物由来","origin_country":"日本","law_kashinho":"既存化学物質（番号は架空）","law_shoboho":"非危険物","pack_container":"ポリエチレン袋入り段ボール箱","shelf_life":"製造後24ヶ月（未開封）","storage":"直射日光を避け、室温で保管","appearance":"白色〜淡黄色の固体","ph_value":"5.5〜7.5（1%水分散液）","cas_numbers":"該当なし（架空の物質）","ghs_hazard":"分類対象外"}$$), NULL, NULL
