-- DOC_VERSION records the bytes the extraction was made from. It is captured from the
-- stage itself, so a later edit of the PDF on the stage shows up as "原本が更新".
INSERT INTO __DB__.__SCHEMA__.DOC_VERSION (STAGE_PATH, MD5, SIZE_BYTES, LAST_MODIFIED, CAPTURED_AT)
SELECT relative_path, md5, size, last_modified, CURRENT_TIMESTAMP() FROM DIRECTORY(@__DB__.__SCHEMA__.RAW)
WHERE relative_path = 'sample_emulsifier/sample-spec_A-100.pdf'
  AND NOT EXISTS (SELECT 1 FROM __DB__.__SCHEMA__.DOC_VERSION WHERE stage_path = 'sample_emulsifier/sample-spec_A-100.pdf');

-- One row per decidable cell. Derived from the tables above, not content.
INSERT INTO __DB__.__SCHEMA__.MASTER_DECISION (product_slug, attr_key)
SELECT p.product_slug, a.attr_key FROM __DB__.__SCHEMA__.PRODUCT p CROSS JOIN __DB__.__SCHEMA__.ATTR_DEF a
WHERE NOT EXISTS (SELECT 1 FROM __DB__.__SCHEMA__.MASTER_DECISION d WHERE d.product_slug = p.product_slug AND d.attr_key = a.attr_key);
INSERT INTO __DB__.__SCHEMA__.FORM_DECISION (product_slug, form_id, field_key)
SELECT p.product_slug, t.form_id, t.field_key FROM __DB__.__SCHEMA__.PRODUCT p CROSS JOIN __DB__.__SCHEMA__.FORM_TEMPLATE t
WHERE NOT EXISTS (SELECT 1 FROM __DB__.__SCHEMA__.FORM_DECISION d WHERE d.product_slug = p.product_slug AND d.form_id = t.form_id AND d.field_key = t.field_key);
